INSERT IGNORE INTO admins (id, name, slug, email, password, admin_type, location, profile_photo, profile_title, designation, profile_description, created_at, updated_at) VALUES
(11, 'Ananya Rao', 'ananya-rao', 'ananya@artistikcity.com', '$2y$10$8uheEMmigBJbrXk8eKxWW.BEfBIWUeZtLGRdZ7a.ms.WP8GuMa31e', 'teacher', 'Bengaluru, India', 'avatar.png', 'Botanical & Watercolour Artist', 'Watercolour Instructor', '<p>Ananya paints flowers, leaves and birds in transparent watercolour. She trained in botanical illustration and has taught more than 2,000 students to see colour and light in nature.</p>', DATE_SUB(CURRENT_TIMESTAMP, INTERVAL 4800 HOUR), CURRENT_TIMESTAMP),
(12, 'Kabir Malhotra', 'kabir-malhotra', 'kabir@artistikcity.com', '$2y$10$8uheEMmigBJbrXk8eKxWW.BEfBIWUeZtLGRdZ7a.ms.WP8GuMa31e', 'teacher', 'New Delhi, India', 'avatar.png', 'Portrait Artist', 'Charcoal & Drawing Instructor', '<p>Kabir draws people. His charcoal portraits have been shown in Delhi and Mumbai, and his classes focus on proportion, values and patient observation.</p>', DATE_SUB(CURRENT_TIMESTAMP, INTERVAL 4560 HOUR), CURRENT_TIMESTAMP),
(13, 'Meera Krishnan', 'meera-krishnan', 'meera@artistikcity.com', '$2y$10$8uheEMmigBJbrXk8eKxWW.BEfBIWUeZtLGRdZ7a.ms.WP8GuMa31e', 'teacher', 'Chennai, India', 'avatar.png', 'Contemporary Painter', 'Acrylic Instructor', '<p>Meera works in bold acrylic colour with palette knives and pours. She helps beginners lose their fear of the blank canvas.</p>', DATE_SUB(CURRENT_TIMESTAMP, INTERVAL 4320 HOUR), CURRENT_TIMESTAMP),
(14, 'Rohit Desai', 'rohit-desai', 'rohit@artistikcity.com', '$2y$10$8uheEMmigBJbrXk8eKxWW.BEfBIWUeZtLGRdZ7a.ms.WP8GuMa31e', 'teacher', 'Mumbai, India', 'avatar.png', 'Landscape Painter', 'Oil Painting Instructor', '<p>Rohit paints landscapes en plein air in oils. He teaches the classical process of underpainting, blocking in and glazing step by step.</p>', DATE_SUB(CURRENT_TIMESTAMP, INTERVAL 4080 HOUR), CURRENT_TIMESTAMP),
(15, 'Sana Qureshi', 'sana-qureshi', 'sana@artistikcity.com', '$2y$10$8uheEMmigBJbrXk8eKxWW.BEfBIWUeZtLGRdZ7a.ms.WP8GuMa31e', 'teacher', 'Hyderabad, India', 'avatar.png', 'Illustrator & Designer', 'Digital Art Instructor', '<p>Sana illustrates books and brands on the iPad. Her classes cover Procreate, lettering and ink sketching on location.</p>', DATE_SUB(CURRENT_TIMESTAMP, INTERVAL 3840 HOUR), CURRENT_TIMESTAMP);
