INSERT IGNORE INTO courses (id, admin_id, medium_id, genre_id, course_type_id, skill_id, category_id, title, slug, sub_title, introduction, introduction_details, summary, summary_details, schedule, schedule_details, age_group, duration, sessions, mini_projects, course_modules, time_required, includes, course_includes, course_highlights, course_for, course_not_for, course_problems_solved, course_learn, course_outcome, course_deliverables, course_prerequisites, course_start_date, course_based, is_free_course, status, created_at, updated_at) VALUES
(101, 11, (SELECT id FROM mediums WHERE medium_slug = 'watercolour' ORDER BY id LIMIT 1), CONCAT_WS(',', (SELECT id FROM genres WHERE genre_slug = 'botanical' ORDER BY id LIMIT 1)), 1, (SELECT id FROM skills WHERE skill_slug = 'intermediate' ORDER BY id LIMIT 1), NULL, 'Botanical Watercolour Masterclass', 'botanical-watercolour-masterclass', 'Paint flowers and leaves with luminous, layered washes.', 'Paint flowers and leaves with luminous, layered washes.', '<p>Paint flowers and leaves with luminous, layered washes. This course is taught live in small groups, with personal feedback on every piece you share.</p><h3>What makes it different</h3><ul><li>Live demonstrations you can pause and ask about</li><li>Clear weekly goals</li><li>A friendly community of learners</li></ul>', '3 modules, 7 lessons and a final project.', '<ul><li><strong>Seeing like a botanist</strong>: Observing structure, Contour drawing</li><li><strong>Layering and glazing</strong>: Wet-on-dry glazes, Soft and lost edges, Greens that sing</li><li><strong>Final botanical plate</strong>: Composition, Finishing details</li></ul>', 'Saturday & Sunday, 11:00 am - 1:00 pm IST', '<p>1 week: Seeing like a botanist<br>2 weeks: Layering and glazing<br>3 weeks: Final botanical plate</p>', '14+ years', '6', '12', '3', '3', '2', NULL, '{"certificate": "yes", "study_material_access": "yes", "medium": "yes", "age": "yes", "skills": "yes"}', '["Live classes", "Personal feedback", "Lifetime access to notes", "Certificate"]', '["Beginners who want structure", "Hobbyists returning to art"]', '["People looking for a recorded-only course"]', '["Not knowing where to start", "Paintings that look flat", "No feedback on your work"]', '["Observing structure", "Contour drawing", "Wet-on-dry glazes", "Soft and lost edges", "Greens that sing", "Composition"]', '<p>You finish with a portfolio piece: finishing details.</p>', '["Finished artworks", "Study notes", "Certificate"]', '<p>Comfortable with basic drawing.</p>', DATE_ADD(CURRENT_DATE, INTERVAL 25 DAY), 'instructor_based', 0, 1, DATE_SUB(CURRENT_TIMESTAMP, INTERVAL 3984 HOUR), DATE_SUB(CURRENT_TIMESTAMP, INTERVAL 120 HOUR)),
(102, 11, (SELECT id FROM mediums WHERE medium_slug = 'watercolour' ORDER BY id LIMIT 1), CONCAT_WS(',', (SELECT id FROM genres WHERE genre_slug = 'wildlife' ORDER BY id LIMIT 1)), 1, (SELECT id FROM skills WHERE skill_slug = 'intermediate' ORDER BY id LIMIT 1), NULL, 'Birds & Wildlife in Watercolour', 'birds-and-wildlife-in-watercolour', 'From sketch to feathers: paint lively birds and animals.', 'From sketch to feathers: paint lively birds and animals.', '<p>From sketch to feathers: paint lively birds and animals. This course is taught live in small groups, with personal feedback on every piece you share.</p><h3>What makes it different</h3><ul><li>Live demonstrations you can pause and ask about</li><li>Clear weekly goals</li><li>A friendly community of learners</li></ul>', '3 modules, 6 lessons and a final project.', '<ul><li><strong>Gesture and anatomy</strong>: Quick gesture sketches, Bird anatomy made simple</li><li><strong>Texture</strong>: Feathers, Bark and rock</li><li><strong>Portrait of a bird</strong>: Planning values, The final painting</li></ul>', 'Saturday & Sunday, 11:00 am - 1:00 pm IST', '<p>2 weeks: Gesture and anatomy<br>2 weeks: Texture<br>2 weeks: Portrait of a bird</p>', '14+ years', '6', '12', '3', '3', '2', NULL, '{"certificate": "yes", "study_material_access": "yes", "medium": "yes", "age": "yes", "skills": "yes"}', '["Live classes", "Personal feedback", "Lifetime access to notes", "Certificate"]', '["Beginners who want structure", "Hobbyists returning to art"]', '["People looking for a recorded-only course"]', '["Not knowing where to start", "Paintings that look flat", "No feedback on your work"]', '["Quick gesture sketches", "Bird anatomy made simple", "Feathers", "Bark and rock", "Planning values", "The final painting"]', '<p>You finish with a portfolio piece: the final painting.</p>', '["Finished artworks", "Study notes", "Certificate"]', '<p>Comfortable with basic drawing.</p>', DATE_ADD(CURRENT_DATE, INTERVAL 40 DAY), 'instructor_based', 0, 1, DATE_SUB(CURRENT_TIMESTAMP, INTERVAL 3888 HOUR), DATE_SUB(CURRENT_TIMESTAMP, INTERVAL 120 HOUR)),
(103, 12, (SELECT id FROM mediums WHERE medium_slug = 'charcoal' ORDER BY id LIMIT 1), CONCAT_WS(',', (SELECT id FROM genres WHERE genre_slug = 'portrait' ORDER BY id LIMIT 1)), 1, (SELECT id FROM skills WHERE skill_slug = 'advanced' ORDER BY id LIMIT 1), NULL, 'Charcoal Portrait Mastery', 'charcoal-portrait-mastery', 'Dramatic, expressive portraits with vine and compressed charcoal.', 'Dramatic, expressive portraits with vine and compressed charcoal.', '<p>Dramatic, expressive portraits with vine and compressed charcoal. This course is taught live in small groups, with personal feedback on every piece you share.</p><h3>What makes it different</h3><ul><li>Live demonstrations you can pause and ask about</li><li>Clear weekly goals</li><li>A friendly community of learners</li></ul>', '3 modules, 7 lessons and a final project.', '<ul><li><strong>Proportions of the head</strong>: The Loomis method, Placing the features</li><li><strong>Light and value</strong>: Five values of light, Subtractive drawing, Skin texture and age</li><li><strong>The finished portrait</strong>: Working from a photo, Final portrait session</li></ul>', 'Saturday & Sunday, 11:00 am - 1:00 pm IST', '<p>2 weeks: Proportions of the head<br>3 weeks: Light and value<br>3 weeks: The finished portrait</p>', '16+ years', '8', '16', '3', '3', '2', NULL, '{"certificate": "yes", "study_material_access": "yes", "medium": "yes", "age": "yes", "skills": "yes"}', '["Live classes", "Personal feedback", "Lifetime access to notes", "Certificate"]', '["Learners with drawing basics"]', '["People looking for a recorded-only course"]', '["Not knowing where to start", "Paintings that look flat", "No feedback on your work"]', '["The Loomis method", "Placing the features", "Five values of light", "Subtractive drawing", "Skin texture and age", "Working from a photo"]', '<p>You finish with a portfolio piece: final portrait session.</p>', '["Finished artworks", "Study notes", "Certificate"]', '<p>Comfortable with basic drawing.</p>', DATE_ADD(CURRENT_DATE, INTERVAL 18 DAY), 'instructor_based', 0, 1, DATE_SUB(CURRENT_TIMESTAMP, INTERVAL 3792 HOUR), DATE_SUB(CURRENT_TIMESTAMP, INTERVAL 120 HOUR)),
(104, 12, (SELECT id FROM mediums WHERE medium_slug = 'pencil-sketch' ORDER BY id LIMIT 1), CONCAT_WS(',', (SELECT id FROM genres WHERE genre_slug = 'portrait' ORDER BY id LIMIT 1)), 1, (SELECT id FROM skills WHERE skill_slug = 'intermediate' ORDER BY id LIMIT 1), NULL, 'Expressive Faces: Graphite Portraits', 'expressive-faces-graphite-portraits', 'Draw faces full of character with graphite pencils.', 'Draw faces full of character with graphite pencils.', '<p>Draw faces full of character with graphite pencils. This course is taught live in small groups, with personal feedback on every piece you share.</p><h3>What makes it different</h3><ul><li>Live demonstrations you can pause and ask about</li><li>Clear weekly goals</li><li>A friendly community of learners</li></ul>', '3 modules, 5 lessons and a final project.', '<ul><li><strong>Features one by one</strong>: Eyes, Lips and nose</li><li><strong>Hair</strong>: Shapes before strands, Curls and movement</li><li><strong>Putting it together</strong>: Full face study</li></ul>', 'Saturday & Sunday, 11:00 am - 1:00 pm IST', '<p>2 weeks: Features one by one<br>2 weeks: Hair<br>2 weeks: Putting it together</p>', '13+ years', '6', '10', '3', '3', '2', NULL, '{"certificate": "yes", "study_material_access": "yes", "medium": "yes", "age": "yes", "skills": "yes"}', '["Live classes", "Personal feedback", "Lifetime access to notes", "Certificate"]', '["Beginners who want structure", "Hobbyists returning to art"]', '["People looking for a recorded-only course"]', '["Not knowing where to start", "Paintings that look flat", "No feedback on your work"]', '["Eyes", "Lips and nose", "Shapes before strands", "Curls and movement", "Full face study"]', '<p>You finish with a portfolio piece: full face study.</p>', '["Finished artworks", "Study notes", "Certificate"]', '<p>Comfortable with basic drawing.</p>', DATE_ADD(CURRENT_DATE, INTERVAL 55 DAY), 'instructor_based', 0, 1, DATE_SUB(CURRENT_TIMESTAMP, INTERVAL 3696 HOUR), DATE_SUB(CURRENT_TIMESTAMP, INTERVAL 120 HOUR)),
