INSERT IGNORE INTO testimonials (id, name, slug, title, photo, description, status, created_at, updated_at) VALUES
(101, 'Ishaan Verma', 'ishaan-verma', 'Eye & feature studies', 'avatar.png', 'I never thought I could draw a realistic eye. The step-by-step lessons and Vaishali''s feedback made it click.', 1, DATE_SUB(CURRENT_TIMESTAMP, INTERVAL 1440 HOUR), CURRENT_TIMESTAMP),
(102, 'Neha Kulkarni', 'neha-kulkarni', 'Charcoal portrait mastery', 'avatar.png', 'Kabir''s classes changed how I see faces. My grandfather''s portrait is now framed in our living room.', 1, DATE_SUB(CURRENT_TIMESTAMP, INTERVAL 1320 HOUR), CURRENT_TIMESTAMP),
(103, 'Arjun Menon', 'arjun-menon', 'Oil painting foundations', 'avatar.png', 'Clear, patient teaching. The underpainting method finally made oils feel manageable.', 1, DATE_SUB(CURRENT_TIMESTAMP, INTERVAL 1200 HOUR), CURRENT_TIMESTAMP),
(104, 'Sophia Fernandes', 'sophia-fernandes', 'Abstract acrylic pouring', 'avatar.png', 'So much fun! I sold my first painting through the marketplace two months after the course.', 1, DATE_SUB(CURRENT_TIMESTAMP, INTERVAL 1080 HOUR), CURRENT_TIMESTAMP),
(105, 'Rahul Gupta', 'rahul-gupta', 'Drawing fundamentals', 'avatar.png', 'At 45 I was sure I had no talent. Now I sketch every evening and love it.', 1, DATE_SUB(CURRENT_TIMESTAMP, INTERVAL 960 HOUR), CURRENT_TIMESTAMP),
(106, 'Emily Clarke', 'emily-clarke', 'Digital illustration', 'avatar.png', 'Taking live classes from London was easy. Sana''s Procreate tips saved me hours.', 1, DATE_SUB(CURRENT_TIMESTAMP, INTERVAL 840 HOUR), CURRENT_TIMESTAMP);
