INSERT IGNORE INTO posts (id, title, subtitle, slug, body, status, posted_by, image, meta_title, meta_description, featured, `like`, dislike, created_at, updated_at) VALUES
(101, 'How to Stretch Watercolour Paper', 'Flat paper, happy paintings: a five-minute routine.', 'how-to-stretch-watercolour-paper', '<p>Buckled paper makes washes pool in the wrong places. Stretching your paper takes five minutes and saves a painting.</p><h2>What you need</h2><ul><li>A board larger than your paper</li><li>Gummed tape</li><li>A clean sponge</li></ul><h2>The steps</h2><ol><li>Wet the paper evenly on both sides.</li><li>Lay it flat on the board.</li><li>Tape all four edges and let it dry flat.</li></ol>', 1, 11, 'demo-101.jpg', NULL, 'Flat paper, happy paintings: a five-minute routine.', 1, 0, 0, DATE_SUB(CURRENT_TIMESTAMP, INTERVAL 1920 HOUR), DATE_SUB(CURRENT_TIMESTAMP, INTERVAL 1680 HOUR)),
(102, 'The Five Values Every Portrait Needs', 'From highlight to core shadow, made simple.', 'the-five-values-every-portrait-needs', '<p>Likeness is mostly about values, not lines. Squint at your reference and find five values: highlight, light, half-tone, core shadow and reflected light.</p><blockquote>If the values are right, the drawing reads from across the room.</blockquote><p>Practise with a simple sphere before moving to faces.</p>', 1, 12, 'demo-102.jpg', NULL, 'From highlight to core shadow, made simple.', 0, 0, 0, DATE_SUB(CURRENT_TIMESTAMP, INTERVAL 1632 HOUR), DATE_SUB(CURRENT_TIMESTAMP, INTERVAL 1392 HOUR)),
(103, 'Palette Knife Painting for Beginners', 'Why a knife can be easier than a brush.', 'palette-knife-painting-for-beginners', '<p>A palette knife forces you to simplify. You cannot fiddle, so you make decisions.</p><h2>Three strokes to learn first</h2><ul><li>The spread</li><li>The scrape</li><li>The dab</li></ul>', 1, 13, 'demo-103.jpg', NULL, 'Why a knife can be easier than a brush.', 0, 0, 0, DATE_SUB(CURRENT_TIMESTAMP, INTERVAL 1344 HOUR), DATE_SUB(CURRENT_TIMESTAMP, INTERVAL 1104 HOUR)),
(104, 'Meet Our Students: Neha''s Portrait Journey', 'From stick figures to a framed portrait in four months.', 'meet-our-students-nehas-portrait-journey', '<p>Neha joined ArtistikCity in spring with no drawing experience. Four months later her charcoal portrait of her grandfather was approved and listed in the marketplace.</p><p>"The feedback on every assignment kept me going," she says.</p>', 1, 2, 'demo-104.jpg', NULL, 'From stick figures to a framed portrait in four months.', 1, 0, 0, DATE_SUB(CURRENT_TIMESTAMP, INTERVAL 1056 HOUR), DATE_SUB(CURRENT_TIMESTAMP, INTERVAL 816 HOUR)),
(105, 'New Workshops This Month', 'Loose florals, pet portraits and palette knife sunsets.', 'new-workshops-this-month', '<p>We have three new weekend workshops: <strong>Loose Florals in One Day</strong>, <strong>Pet Portraits in Charcoal</strong> and <strong>Palette Knife Sunset</strong>. Seats are limited to keep the groups small.</p>', 1, 1, 'demo-105.jpg', NULL, 'Loose florals, pet portraits and palette knife sunsets.', 0, 0, 0, DATE_SUB(CURRENT_TIMESTAMP, INTERVAL 768 HOUR), DATE_SUB(CURRENT_TIMESTAMP, INTERVAL 528 HOUR)),
(106, 'Choosing an iPad for Digital Art', 'What matters and what does not.', 'choosing-an-ipad-for-digital-art', '<p>Draft: compare screen sizes, pencil support and storage. Add a short buying guide for students.</p>', 0, 15, 'demo-106.jpg', NULL, 'What matters and what does not.', 0, 0, 0, DATE_SUB(CURRENT_TIMESTAMP, INTERVAL 480 HOUR), DATE_SUB(CURRENT_TIMESTAMP, INTERVAL 240 HOUR));
