INSERT IGNORE INTO faqs (id, category, question, answer, sort_order, status, created_at, updated_at) VALUES
(101, 'Classes', 'What if I miss a live class?', '<p>Every session is recorded and appears in your classroom within a day, so you can catch up and still send your work for feedback.</p>', 10, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
(102, 'Classes', 'How big are the groups?', '<p>Courses have up to 20 students and workshops up to 12, so the instructor can look at everyone''s work.</p>', 11, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
(103, 'Payments', 'Can I get a refund?', '<p>Write to us before the second session and we will refund you in full. Contact us for anything after that.</p>', 12, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
(104, 'Kids', 'Are there classes for children?', '<p>Yes. Look for the courses marked 8-12 years and our weekend art camp for 6-12 year olds.</p>', 13, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
(105, 'Marketplace', 'How are originals shipped?', '<p>Originals are packed flat or rolled, insured and shipped with tracking within five working days.</p>', 14, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
