(101, 'October at the studio: new workshops and student stars', 'Three new workshops and Neha''s portrait story', '<h2>Hello from the studio!</h2><p>This month we are launching three weekend workshops: loose florals, pet portraits in charcoal and a palette knife sunset.</p><p>We are also celebrating Neha, whose charcoal portrait is now in the marketplace.</p><p><a href="/courses?type=workshop">See the workshops</a></p>', 'sent', 24, 24, 0, 1, DATE_SUB(CURRENT_TIMESTAMP, INTERVAL 216 HOUR), DATE_SUB(CURRENT_TIMESTAMP, INTERVAL 264 HOUR), DATE_SUB(CURRENT_TIMESTAMP, INTERVAL 216 HOUR)),
(102, 'November preview: oil painting and digital art', 'Early access for subscribers', '<p>Draft: announce the November batch of Oil Painting Foundations and Digital Illustration with Procreate.</p>', 'draft', 0, 0, 0, 1, NULL, DATE_SUB(CURRENT_TIMESTAMP, INTERVAL 24 HOUR), DATE_SUB(CURRENT_TIMESTAMP, INTERVAL 24 HOUR));
